use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-ready-c7a");let a=read("/tmp/zopro-grouping-module/production-source-manifest.json");let parent=read("/tmp/zopro-ready-arithmetic/native-plan.json");let mut pins:BTreeMap<String,String>=serde_json::from_value(read("/tmp/zopro-ready-arithmetic/source-pins.json")).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}
 for(p,h)in a["source_files_sha256"].as_object().unwrap(){let p=r.join("accepted").join(p);assert_eq!(hash(&p),h.as_str().unwrap());pins.insert(p.to_str().unwrap().into(),h.as_str().unwrap().into());}
 fs::create_dir_all(r.join("support")).unwrap();fs::copy("/tmp/zopro-g2-owned-finish/candidate/crates/zopro-bench/examples/cpu-sdk.rs",r.join("sdk.rs")).unwrap();fs::copy("/tmp/zopro-g2-owned-finish/candidate/crates/zopro-bench/examples/support/perf.rs",r.join("support/perf.rs")).unwrap();
 let flags=a["rustflags"].as_str().unwrap().replace("target-cpu=native","target-cpu=znver4");let mut environment=a["environment"].clone();environment["RAYON_NUM_THREADS"]=json!("4");environment["CARGO_BUILD_JOBS"]=json!("16");
 let mut steps=vec![json!({"kind":"command","name":"compiler","argv":["rustc","-Vv"]})];
 for variant in ["accepted","diagnostic"]{let source=if variant=="accepted"{r.join("accepted")}else{Path::new("/tmp/zopro-ready-arithmetic/candidate").to_path_buf()};let mut env=json!({"RUSTFLAGS":flags,"CARGO_TARGET_DIR":r.join(format!("target-{variant}"))});if variant=="diagnostic"{env["RUSTFLAGS"]=json!(format!("{flags} --cfg zopro_ready_arithmetic"));}
  for (label,package) in [("field","zopro-bn254"),("core","zopro-core")]{steps.push(json!({"kind":"command","name":format!("{variant}-{label}"),"argv":["cargo","test","--manifest-path",source.join("Cargo.toml"),"--offline","--locked","--release","-p",package,"--lib","--","--test-threads=1"],"environment":env,"unfiltered":true,"timeout_seconds":1200}));}
  let original=parent["steps"].as_array().unwrap().iter().find(|s|s["name"]=="on-prover").unwrap();let mut raw=original.clone();raw["name"]=json!(format!("{variant}-prover"));raw["argv"][3]=json!(source.join("Cargo.toml"));raw["environment"]=env.clone();steps.push(raw);
  steps.push(json!({"kind":"command","name":format!("{variant}-libraries"),"argv":["cargo","build","--manifest-path",source.join("Cargo.toml"),"--offline","--locked","--release","-p","zopro-bench","--lib","--message-format=json"],"environment":env,"timeout_seconds":1200}));
  let(driver,support)=if variant=="accepted"{(r.join("sdk.rs"),r.join("support/perf.rs"))}else{(source.join("crates/zopro-bench/examples/cpu-sdk.rs"),source.join("crates/zopro-bench/examples/support/perf.rs"))};
  steps.push(json!({"kind":"link-sdk","name":variant,"artifacts":r.join(format!("native/{variant}-libraries/stdout.log")),"driver":driver,"additional_sources":[support],"rustc_flags":["-O","-C","target-cpu=znver4","-C","lto=fat","-C","codegen-units=1"],"timeout_seconds":1200}));
 }
 for p in["design.md","prepare-build.rs","prepare.json","sdk.rs","support/perf.rs"]{let p=r.join(p);pins.insert(p.to_str().unwrap().into(),hash(&p));}
 fs::write(r.join("build-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("native-plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"environment":environment,"source_pins":r.join("build-pins.json"),"steps":steps})).unwrap()).unwrap();println!("Frozen C7a znver4 cleanaccepted/diagnostic builds, {} source/input pins; no cloud resources",pins.len());}
